// Lab C.1: what every feed path receives, and the provided pieces each backend
// implements. Provided; you do not edit this file.
//
// A feed path is one function that takes a FeedJob and does, in its own kind of
// memory, what the book's Fig. C.1 (p. 627) does: put a table where a kernel can
// read it, run the kernel, and hand the result to CPU code.
#pragma once
#include <cstddef>
#include <cstdint>

struct FeedJob {
    int rows;          // the table: rows x cols floats, row-major (a vocabulary of embedding rows)
    int cols;          // floats per row (the embedding width)
    const int* ids_h;  // `count` row indices, each in [0, rows), in host memory the driver owns
    int count;         // rows of the result: one per id
    int passes;        // launch gatherAdd this many times over the same data
    // Writes rows * cols floats into `table`, as fread does in Fig. C.1. Call it
    // exactly once, with a pointer the CPU may write through.
    void (*produce)(float* table, void* ctx);
    // Reads count * cols floats from `out`, as use_data does in Fig. C.1. Call it
    // exactly once, after the last pass has finished, with a pointer the CPU may read.
    void (*consume)(const float* out, void* ctx);
    void* ctx;         // pass it back to produce and consume
};

// Byte counts of the three arrays. `out` starts at zero and ends as
// passes * table[ids[r]] in row r.
inline size_t feedTableBytes(const FeedJob* job) { return (size_t)job->rows * (size_t)job->cols * sizeof(float); }
inline size_t feedIdsBytes(const FeedJob* job) { return (size_t)job->count * sizeof(int); }
inline size_t feedOutBytes(const FeedJob* job) { return (size_t)job->count * (size_t)job->cols * sizeof(float); }

// What the provided launcher saw, for the driver's structural test: did the
// kernel read the very memory produce wrote, or a copy of it?
struct FeedRecord {
    const void* table;    // CUDA family: the table pointer of the last launchGatherAdd.
                          // Metal: `contents` of the last table buffer encodeGatherAdd bound (NULL if private).
    int launches;         // launches (CUDA family) or dispatches encoded (Metal) since the last reset
    int tablePrivate;     // Metal: 1 if that buffer's storage mode is private, else 0. CUDA family: -1.
    double gpu_copy_s;    // Metal: GPU seconds of the command buffers passed to waitFor(..., kCopyWork). Else -1.
    double gpu_kernel_s;  // Metal: GPU seconds of the command buffers passed to waitFor(..., kKernelWork). Else -1.
};
FeedRecord feedRecord();
void feedResetRecord();

#if defined(__OBJC__)
// ---- Metal: provided in launch.mm ----
#import <Metal/Metal.h>
enum FeedWork { kCopyWork = 0, kKernelWork = 1 };
// Encodes one pass of gather_add (kernel.metal) into an open compute encoder.
void encodeGatherAdd(id<MTLComputeCommandEncoder> encoder, id<MTLComputePipelineState> pipeline,
                     id<MTLBuffer> table, id<MTLBuffer> ids, id<MTLBuffer> out, uint32_t count, uint32_t cols);
// Waits for a committed command buffer. Returns 0, or prints why the GPU did
// not run it and returns 1. Adds its GPU time to the copy or the kernel total.
int waitFor(id<MTLCommandBuffer> commandBuffer, FeedWork kind);
// ---- Metal: yours, in launch.mm. Each returns 0, or 1 after printing what failed. ----
int feedPrivateCopy(id<MTLDevice> device, id<MTLCommandQueue> queue, id<MTLComputePipelineState> pipeline,
                    const FeedJob* job);
int feedNoCopy(id<MTLDevice> device, id<MTLCommandQueue> queue, id<MTLComputePipelineState> pipeline,
               const FeedJob* job);
int feedShared(id<MTLDevice> device, id<MTLCommandQueue> queue, id<MTLComputePipelineState> pipeline,
               const FeedJob* job);
#else
// ---- CUDA, HIP and the emulator: provided in kernel.cu ----
// One pass: out[r*cols + c] += table[ids[r]*cols + c] for r < count, c < cols.
// Returns once the launch is queued, as any kernel launch does.
void launchGatherAdd(const float* table, const int* ids, float* out, int count, int cols);
// ---- yours, in kernel.cu. Each returns 0, or 1 after printing a checked error. ----
int feedExplicit(const FeedJob* job);
int feedMapped(const FeedJob* job);
int feedManaged(const FeedJob* job);
// ---- provided in ../shared/probe.cu ----
// The three attributes that name this device's unified-memory paradigm
// (notes/today/appC-facts.md A14, B5), and the paradigm's name:
// "limited", "full-managed", "full-hmm", "full-ats", or "emulator" (attributes -1).
const char* queryManagedParadigm(int* concurrentManaged, int* pageableAccess, int* usesHostPageTables);
// Pinned host-to-device and device-to-device cudaMemcpy of `bytes`, timed with
// events, best of `reps`. Device bandwidth counts the bytes read plus written.
// Returns 0, or 1 after printing a checked error.
int probeBandwidth(size_t bytes, int reps, double* link_gb_per_s, double* device_gb_per_s);
#endif

